package db

import (
	"context"
	"errors"
	"fmt"
	"regexp"
	"slices"
	"strings"
	"time"
	"unicode"

	"github.com/jackc/pgx/v5"
)

// Finding labels (CONTRACT §2.15 "Labels and scorecards", migration 14):
// append-only quality labels on proposed fixes, imported from files by
// `earmark labels import`. A label is about one fix to one chunk revision —
// its correction_key is generated by the database with the same expression
// as transcript_findings.correction_key — so it scores every recipe that
// proposed that fix, before or after the label was made.

// Label values (finding_labels.label).
const (
	LabelGood    = "good"
	LabelJunk    = "junk"
	LabelPartial = "partial" // right target, still wrong (counts against precision)
	LabelUnsure  = "unsure"  // excluded from precision
)

// Labels lists the label values.
var Labels = []string{LabelGood, LabelJunk, LabelPartial, LabelUnsure}

// How an imported label was tied to a chunk revision (finding_labels.resolved_by).
const (
	LabelResolvedFinding = "finding" // the named finding's recorded chunk hash
	LabelResolvedHash    = "hash"    // the item's own chunk_text_sha256
	LabelResolvedChunk   = "chunk"   // the current chunk; the span (and context) found in its text
)

// Reasons an item is not imported (LabelUnresolved.Reason).
const (
	UnresolvedInvalid             = "invalid"
	UnresolvedFindingNotFound     = "finding_not_found"
	UnresolvedFindingTextMismatch = "finding_text_mismatch"
	UnresolvedHashMismatch        = "hash_mismatch"
	UnresolvedNoTarget            = "no_target"
	UnresolvedChunkNotFound       = "chunk_not_found"
	UnresolvedUnknownRevision     = "unknown_revision"
	UnresolvedNoHash              = "no_hash"
	UnresolvedSpanNotInChunk      = "span_not_in_chunk"
	UnresolvedContextNotInChunk   = "context_not_in_chunk"
)

// MaxLabelImport caps the items of one import (one transaction).
const MaxLabelImport = 50000

var (
	// labelSetRe and labelerRe mirror finding_labels' CHECKs, so a bad flag
	// fails before anything is read.
	labelSetRe = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._:/-]*$`)
	labelerRe  = regexp.MustCompile(`^[a-z][a-z0-9_-]*:\S+$`)
	anyUUIDRe  = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)
)

// LabelItem is one label to import. It names its target either by
// FindingID (the finding's recorded chunk hash and texts are used) or by
// ChunkID + Original + Correction, optionally pinned by ChunkTextSHA256.
type LabelItem struct {
	// SourceRef is the item's id in its source file (J003, Q120, …).
	SourceRef       string
	FindingID       string
	ChunkID         string
	ChunkTextSHA256 string
	Original        string
	Correction      string
	IssueType       string
	// Context is a snippet of the chunk text the labeller saw; when set, a
	// chunk-resolved item must find it in the current chunk.
	Context string
	Label   string
	Reason  string
	// LabelledAt is when the label was made (zero = the import time).
	LabelledAt time.Time
}

// LabelImport is one `earmark labels import` run.
type LabelImport struct {
	Set     string
	Labeler string
	Items   []LabelItem
	// DryRun resolves and counts in a read-only transaction; nothing is written.
	DryRun bool
	// RequireHash refuses items that would resolve by span alone: each must
	// name a finding or a chunk_text_sha256.
	RequireHash bool
}

// Validate checks the set and labeler names.
func (imp LabelImport) Validate() error {
	switch {
	case !labelSetRe.MatchString(imp.Set) || len(imp.Set) > 128:
		return fmt.Errorf("label set %q: use letters, digits and . _ : / - (≤128, starting with a letter or digit)", imp.Set)
	case !labelerRe.MatchString(imp.Labeler) || len(imp.Labeler) > 128:
		return fmt.Errorf("labeler %q: use kind:name, e.g. human:justin or opus:bakeoff-2026-10", imp.Labeler)
	case len(imp.Items) > MaxLabelImport:
		return fmt.Errorf("%d items: one import takes at most %d", len(imp.Items), MaxLabelImport)
	}
	return nil
}

// LabelUnresolved is an item that was not imported, and why.
type LabelUnresolved struct {
	Index     int    `json:"index"` // 0-based position in the input
	SourceRef string `json:"source_ref,omitempty"`
	Reason    string `json:"reason"`
	Detail    string `json:"detail,omitempty"`
}

// LabelImportReport counts an import.
type LabelImportReport struct {
	DryRun bool `json:"dry_run"`
	Items  int  `json:"items"`
	// Inserted are new rows (in a dry run: rows that would be inserted).
	Inserted int `json:"inserted"`
	// Skipped are identical to a stored label or to an earlier item.
	Skipped    int `json:"skipped"`
	Unresolved int `json:"unresolved"`
	// ByResolution and ByLabel count the resolved items (inserted + skipped).
	ByResolution    map[string]int    `json:"by_resolution"`
	ByLabel         map[string]int    `json:"by_label"`
	UnresolvedItems []LabelUnresolved `json:"unresolved_items,omitempty"`
}

// resolvedLabel is an item tied to its target.
type resolvedLabel struct {
	idx                int
	item               LabelItem
	findingID, chunkID *string
	sha                *string
	original, correctn string
	issueType          string
	by                 string
	dedupeKey          string
}

// labelTargetsSQL fetches, per item, the named finding and the chunk it
// addresses (the item's chunk, else the finding's). The chunk hash is the
// one every finding records: sha256 of COALESCE(source_text, text).
var labelTargetsSQL = `
	SELECT it.ord,
	       f.id::text, f.chunk_id::text, f.chunk_text_sha256, f.original_text,
	       COALESCE(f.suggested_correction, ''), f.issue_type,
	       c.id::text, encode(sha256(convert_to(COALESCE(c.source_text, c.text), 'UTF8')), 'hex'),
	       COALESCE(c.source_text, c.text), c.text
	  FROM unnest($1::int[], $2::uuid[], $3::uuid[]) AS it(ord, finding_id, chunk_id)
	  LEFT JOIN transcript_findings f ON f.id = it.finding_id
	  LEFT JOIN transcript_chunks c ON c.id = COALESCE(it.chunk_id, f.chunk_id)`

// labelKnownRevisionsSQL: which (chunk, hash) pairs some finding — live or
// archived — recorded, i.e. a chunk revision earmark has seen.
var labelKnownRevisionsSQL = `
	SELECT p.ord
	  FROM unnest($1::int[], $2::uuid[], $3::text[]) AS p(ord, chunk_id, sha)
	 WHERE EXISTS (SELECT 1 FROM transcript_findings f
	                WHERE f.chunk_id = p.chunk_id AND f.chunk_text_sha256 = p.sha)`

// labelDedupeSQL computes each resolved item's dedupe key with the table's
// own functions and whether a stored label already has it.
var labelDedupeSQL = `
	SELECT it.ord, k.dedupe_key,
	       EXISTS (SELECT 1 FROM finding_labels l WHERE l.dedupe_key = k.dedupe_key)
	  FROM unnest($3::int[], $4::text[], $5::text[], $6::text[], $7::uuid[], $8::text[], $9::text[])
	       AS it(ord, sha, original, correction, finding_id, label, reason)
	 CROSS JOIN LATERAL (
	       SELECT finding_labels_dedupe_key($1, $2,
	                  finding_correction_key(it.sha, it.original, it.correction),
	                  it.finding_id, it.label, NULLIF(it.reason, '')) AS dedupe_key) k`

// insertLabelsSQL appends the labels; an identical label (dedupe_key)
// already stored — e.g. by a concurrent import — is skipped.
var insertLabelsSQL = `
	INSERT INTO finding_labels (label_set, labeler, label, reason, chunk_id, chunk_text_sha256,
	                            original, correction, issue_type, finding_id, resolved_by,
	                            source_ref, labelled_at)
	SELECT $1, $2, it.label, NULLIF(it.reason, ''), it.chunk_id, it.sha, it.original, it.correction,
	       NULLIF(it.issue_type, ''), it.finding_id, it.resolved_by, NULLIF(it.source_ref, ''),
	       COALESCE(it.labelled_at, clock_timestamp())
	  FROM unnest($3::text[], $4::text[], $5::uuid[], $6::text[], $7::text[], $8::text[], $9::text[],
	              $10::uuid[], $11::text[], $12::text[], $13::timestamptz[])
	       WITH ORDINALITY AS it(label, reason, chunk_id, sha, original, correction, issue_type,
	                             finding_id, resolved_by, source_ref, labelled_at, ord)
	 ORDER BY it.ord
	ON CONFLICT (dedupe_key) DO NOTHING
	RETURNING id`

// labelTarget is one labelTargetsSQL row.
type labelTarget struct {
	findingID, findingChunk, findingSHA, findingOrig, findingCorr, findingIssue *string
	chunkID, chunkSHA, chunkSource, chunkText                                   *string
}

// ImportLabels resolves and appends labels (CONTRACT §2.15 "Labels and
// scorecards") in one transaction — read-only when imp.DryRun. Items that
// cannot be tied to a chunk revision are reported, never guessed.
func (db *DB) ImportLabels(ctx context.Context, imp LabelImport) (LabelImportReport, error) {
	rep := LabelImportReport{DryRun: imp.DryRun, Items: len(imp.Items),
		ByResolution: map[string]int{}, ByLabel: map[string]int{}}
	if err := imp.Validate(); err != nil {
		return rep, err
	}
	opts := pgx.TxOptions{}
	if imp.DryRun {
		opts.AccessMode = pgx.ReadOnly
	}
	tx, err := db.pool.BeginTx(ctx, opts)
	if err != nil {
		return rep, fmt.Errorf("begin label import: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	resolved, err := resolveLabels(ctx, tx, imp, &rep)
	if err != nil {
		return rep, err
	}
	fresh, err := dedupeLabels(ctx, tx, imp, resolved, &rep)
	if err != nil {
		return rep, err
	}
	if imp.DryRun {
		rep.Inserted = len(fresh)
		return rep, nil
	}
	n, err := insertLabels(ctx, tx, imp, fresh)
	if err != nil {
		return rep, err
	}
	rep.Inserted = n
	rep.Skipped += len(fresh) - n // stored concurrently
	if err := tx.Commit(ctx); err != nil {
		return rep, fmt.Errorf("commit label import: %w", err)
	}
	return rep, nil
}

func (r *LabelImportReport) unresolved(i int, it LabelItem, reason, detail string) {
	r.Unresolved++
	r.UnresolvedItems = append(r.UnresolvedItems, LabelUnresolved{Index: i, SourceRef: it.SourceRef, Reason: reason, Detail: detail})
}

// validLabelItem checks an item's shape before any lookup.
func validLabelItem(it LabelItem) error {
	switch {
	case !slices.Contains(Labels, it.Label):
		return fmt.Errorf("label %q is not one of %s", it.Label, strings.Join(Labels, ", "))
	case it.FindingID != "" && !anyUUIDRe.MatchString(it.FindingID):
		return fmt.Errorf("finding_id %q is not a uuid", it.FindingID)
	case it.ChunkID != "" && !anyUUIDRe.MatchString(it.ChunkID):
		return fmt.Errorf("chunk_id %q is not a uuid", it.ChunkID)
	case it.ChunkTextSHA256 != "" && !sha256HexRe.MatchString(it.ChunkTextSHA256):
		return fmt.Errorf("chunk_text_sha256 %q is not lowercase hex sha256", it.ChunkTextSHA256)
	case len(it.Reason) > 2000:
		return errors.New("reason is longer than 2000 bytes")
	}
	return nil
}

func resolveLabels(ctx context.Context, tx pgx.Tx, imp LabelImport, rep *LabelImportReport) ([]resolvedLabel, error) {
	var (
		ords             []int32
		findings, chunks []*string
		valid            = make([]bool, len(imp.Items))
	)
	for i, it := range imp.Items {
		if err := validLabelItem(it); err != nil {
			rep.unresolved(i, it, UnresolvedInvalid, err.Error())
			continue
		}
		valid[i] = true
		ords = append(ords, int32(i)) //nolint:gosec // i < MaxLabelImport
		findings = append(findings, optUUID(it.FindingID))
		chunks = append(chunks, optUUID(it.ChunkID))
	}
	targets := make(map[int]labelTarget, len(ords))
	if len(ords) > 0 {
		rows, err := tx.Query(ctx, labelTargetsSQL, ords, findings, chunks)
		if err != nil {
			return nil, fmt.Errorf("label targets: %w", err)
		}
		for rows.Next() {
			var ord int32
			var t labelTarget
			if err := rows.Scan(&ord, &t.findingID, &t.findingChunk, &t.findingSHA, &t.findingOrig,
				&t.findingCorr, &t.findingIssue, &t.chunkID, &t.chunkSHA, &t.chunkSource, &t.chunkText); err != nil {
				rows.Close()
				return nil, fmt.Errorf("label targets: %w", err)
			}
			targets[int(ord)] = t
		}
		rows.Close()
		if err := rows.Err(); err != nil {
			return nil, fmt.Errorf("label targets: %w", err)
		}
	}

	// Items whose hash is not the current chunk's: is it a revision some
	// finding recorded?
	var kOrds []int32
	var kChunks []*string
	var kSHAs []string
	for i, it := range imp.Items {
		t, ok := targets[i]
		if !valid[i] || !ok || it.ChunkTextSHA256 == "" || it.ChunkID == "" {
			continue
		}
		if t.chunkSHA == nil || *t.chunkSHA != it.ChunkTextSHA256 {
			kOrds = append(kOrds, int32(i)) //nolint:gosec // i < MaxLabelImport
			kChunks = append(kChunks, optUUID(it.ChunkID))
			kSHAs = append(kSHAs, it.ChunkTextSHA256)
		}
	}
	known := map[int]bool{}
	if len(kOrds) > 0 {
		rows, err := tx.Query(ctx, labelKnownRevisionsSQL, kOrds, kChunks, kSHAs)
		if err != nil {
			return nil, fmt.Errorf("label revisions: %w", err)
		}
		ks, err := pgx.CollectRows(rows, pgx.RowTo[int32])
		if err != nil {
			return nil, fmt.Errorf("label revisions: %w", err)
		}
		for _, k := range ks {
			known[int(k)] = true
		}
	}

	var out []resolvedLabel
	for i, it := range imp.Items {
		if !valid[i] {
			continue
		}
		r, reason, detail := resolveLabel(it, targets[i], known[i], imp.RequireHash)
		if reason != "" {
			rep.unresolved(i, it, reason, detail)
			continue
		}
		r.idx = i
		out = append(out, r)
	}
	return out, nil
}

// resolveLabel ties one item to a chunk revision (see LabelResolved*) or
// says why it cannot. Pure: t is what the database holds for the item, and
// knownRevision whether a finding recorded the item's (chunk, hash).
func resolveLabel(it LabelItem, t labelTarget, knownRevision, requireHash bool) (resolvedLabel, string, string) {
	r := resolvedLabel{item: it, issueType: it.IssueType}
	if it.FindingID != "" && t.findingID != nil {
		switch {
		case it.Original != "" && normSpan(it.Original) != normSpan(strOr(t.findingOrig)):
			return r, UnresolvedFindingTextMismatch, fmt.Sprintf("original %q, finding has %q", it.Original, strOr(t.findingOrig))
		case it.Correction != "" && normSpan(it.Correction) != normSpan(strOr(t.findingCorr)):
			return r, UnresolvedFindingTextMismatch, fmt.Sprintf("correction %q, finding has %q", it.Correction, strOr(t.findingCorr))
		case it.ChunkTextSHA256 != "" && it.ChunkTextSHA256 != strOr(t.findingSHA):
			return r, UnresolvedHashMismatch, "the finding records another chunk revision"
		}
		r.findingID, r.chunkID, r.sha = t.findingID, t.findingChunk, t.findingSHA
		if r.sha != nil && *r.sha == "" {
			r.sha = nil
		}
		r.original, r.correctn = strOr(t.findingOrig), strOr(t.findingCorr)
		if r.issueType == "" {
			r.issueType = strOr(t.findingIssue)
		}
		r.by = LabelResolvedFinding
		return r, "", ""
	}
	if it.FindingID != "" && it.ChunkID == "" {
		return r, UnresolvedFindingNotFound, it.FindingID
	}
	if it.ChunkID == "" {
		return r, UnresolvedNoTarget, "name a finding_id, or a chunk_id with original and correction"
	}
	if strings.TrimSpace(it.Original) == "" {
		return r, UnresolvedInvalid, "original is empty"
	}
	chunk := strings.ToLower(it.ChunkID)
	r.chunkID, r.original, r.correctn = &chunk, it.Original, it.Correction
	if it.ChunkTextSHA256 != "" {
		if (t.chunkSHA != nil && *t.chunkSHA == it.ChunkTextSHA256) || knownRevision {
			sha := it.ChunkTextSHA256
			r.sha, r.by = &sha, LabelResolvedHash
			return r, "", ""
		}
		if t.chunkID == nil {
			return r, UnresolvedChunkNotFound, it.ChunkID
		}
		return r, UnresolvedUnknownRevision, "neither the current chunk nor any finding has this chunk_text_sha256"
	}
	if t.chunkID == nil {
		return r, UnresolvedChunkNotFound, it.ChunkID
	}
	if requireHash {
		return r, UnresolvedNoHash, "--require-hash: the item names no chunk_text_sha256"
	}
	if !strings.Contains(normSpan(strOr(t.chunkSource)), normSpan(it.Original)) {
		return r, UnresolvedSpanNotInChunk, "the current chunk text does not contain the original span"
	}
	if it.Context != "" {
		ctxN := normSpan(it.Context)
		if !strings.Contains(normSpan(strOr(t.chunkSource)), ctxN) && !strings.Contains(normSpan(strOr(t.chunkText)), ctxN) {
			return r, UnresolvedContextNotInChunk, "the current chunk text does not contain the labelled context"
		}
	}
	r.sha, r.by = t.chunkSHA, LabelResolvedChunk
	return r, "", ""
}

func dedupeLabels(ctx context.Context, tx pgx.Tx, imp LabelImport, resolved []resolvedLabel, rep *LabelImportReport) ([]resolvedLabel, error) {
	if len(resolved) == 0 {
		return nil, nil
	}
	n := len(resolved)
	ords := make([]int32, n)
	shas, findings := make([]*string, n), make([]*string, n)
	origs, corrs, labels, reasons := make([]string, n), make([]string, n), make([]string, n), make([]string, n)
	for i, r := range resolved {
		ords[i] = int32(i) //nolint:gosec // n ≤ MaxLabelImport
		shas[i], findings[i] = r.sha, r.findingID
		origs[i], corrs[i], labels[i], reasons[i] = r.original, r.correctn, r.item.Label, strings.TrimSpace(r.item.Reason)
	}
	rows, err := tx.Query(ctx, labelDedupeSQL, imp.Set, imp.Labeler, ords, shas, origs, corrs, findings, labels, reasons)
	if err != nil {
		return nil, fmt.Errorf("label dedupe: %w", err)
	}
	exists := make([]bool, n)
	for rows.Next() {
		var ord int32
		var key string
		var ex bool
		if err := rows.Scan(&ord, &key, &ex); err != nil {
			rows.Close()
			return nil, fmt.Errorf("label dedupe: %w", err)
		}
		resolved[ord].dedupeKey, exists[ord] = key, ex
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("label dedupe: %w", err)
	}
	seen := map[string]bool{}
	var fresh []resolvedLabel
	for i, r := range resolved {
		rep.ByResolution[r.by]++
		rep.ByLabel[r.item.Label]++
		if exists[i] || seen[r.dedupeKey] {
			rep.Skipped++
			continue
		}
		seen[r.dedupeKey] = true
		fresh = append(fresh, r)
	}
	return fresh, nil
}

func insertLabels(ctx context.Context, tx pgx.Tx, imp LabelImport, fresh []resolvedLabel) (int, error) {
	if len(fresh) == 0 {
		return 0, nil
	}
	n := len(fresh)
	labels, reasons, shas := make([]string, n), make([]string, n), make([]*string, n)
	chunks, findings := make([]*string, n), make([]*string, n)
	origs, corrs, issues, bys, refs := make([]string, n), make([]string, n), make([]string, n), make([]string, n), make([]string, n)
	ats := make([]*time.Time, n)
	for i, r := range fresh {
		labels[i], reasons[i], shas[i] = r.item.Label, strings.TrimSpace(r.item.Reason), r.sha
		chunks[i], findings[i] = r.chunkID, r.findingID
		origs[i], corrs[i], issues[i], bys[i], refs[i] = r.original, r.correctn, r.issueType, r.by, r.item.SourceRef
		if !r.item.LabelledAt.IsZero() {
			at := r.item.LabelledAt
			ats[i] = &at
		}
	}
	rows, err := tx.Query(ctx, insertLabelsSQL, imp.Set, imp.Labeler,
		labels, reasons, chunks, shas, origs, corrs, issues, findings, bys, refs, ats)
	if err != nil {
		return 0, fmt.Errorf("insert labels: %w", err)
	}
	ids, err := pgx.CollectRows(rows, pgx.RowTo[int64])
	if err != nil {
		return 0, fmt.Errorf("insert labels: %w", err)
	}
	return len(ids), nil
}

func optUUID(s string) *string {
	if s == "" {
		return nil
	}
	l := strings.ToLower(s)
	return &l
}

func strOr(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

// normSpan is the span comparison the import uses to check an item against
// a chunk or a finding: Unicode lower case, every whitespace run (NBSP and
// the other Unicode spaces included) collapsed to one space, trimmed. It is
// a containment check, not the correction key — the key is always computed
// by the database.
func normSpan(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	space := false
	for _, r := range s {
		if unicode.IsSpace(r) || unicode.Is(unicode.Zs, r) || r == 0xFEFF {
			space = true
			continue
		}
		if space && b.Len() > 0 {
			b.WriteByte(' ')
		}
		space = false
		b.WriteRune(unicode.ToLower(r))
	}
	return b.String()
}
